command:
T=$(mktemp -d) && ../run.sh toolkit --output $T/toolkit.excalidrawlib | tee $T/out.json && python3 - $T/out.json $T/toolkit.excalidrawlib <<'PYCODE'
import json,sys
receipt=json.load(open(sys.argv[1]))
lib=json.load(open(sys.argv[2]))
if receipt['status']!='PASS' or receipt['animation_tokens']<5 or receipt['nodes']<28:
    raise SystemExit(receipt)
if lib['type']!='excalidrawlib' or len(lib['libraryItems'])<33:
    raise SystemExit('bad library')
titles={e.get('customData',{}).get('opsExcalidraw',{}).get('title') for item in lib['libraryItems'] for e in item['elements'] if e.get('customData')}
for required in ('Graph DB','Vector store','Tau DAG','Gate','QRA','Control','Message queue','Load balancer','Decision','Risk'):
    if required not in titles:
        raise SystemExit(f'missing node: {required}')
print('OPS_EXCALIDRAW_TOOLKIT_OK', receipt['nodes'], receipt['animation_tokens'])
PYCODE

T=$(mktemp -d) && ../run.sh compile fixtures/interview-board.excalidraw $T/scene.yml | tee $T/compile.json && python3 - $T/compile.json $T/scene.yml <<'PYCODE'
import json,sys
receipt=json.load(open(sys.argv[1]))
scene=json.load(open(sys.argv[2]))
if receipt['schema']!='ops_excalidraw.compile.v1' or receipt['timeline_events']!=8:
    raise SystemExit(receipt)
recipes={event['recipe'] for event in scene['timeline']['events']}
for recipe in ['fade-slide-y','draw-stroke','halo-pulse','color-pin','pulse']:
    if recipe not in recipes:
        raise SystemExit(f'missing {recipe}')
print('OP_EXCALIDRAW_TIMELINE_OK', len(scene['timeline']['events']))
PYCODE

T=$(mktemp -d) && python3 - <<'PYCODE' > $T/ambiguous.excalidraw
import json
def node(id, role, y):
    return {'id': id, 'type': 'rectangle', 'x': 0, 'y': y, 'width': 100, 'height': 50, 'isDeleted': False, 'groupIds': [], 'customData': {'opsExcalidraw': {'kind': 'node', 'role': role, 'title': id}}}
scene = {'type': 'excalidraw', 'version': 2, 'appState': {}, 'files': {}, 'elements': [node('source', 'source', 0), node('target-a', 'target', 80), node('target-b', 'target', 160), {'id': 'anim', 'type': 'diamond', 'x': 0, 'y': 220, 'width': 50, 'height': 50, 'isDeleted': False, 'groupIds': [], 'customData': {'opsExcalidraw': {'kind': 'animation', 'preset': 'pulse', 'targetId': 'target', 'startMs': 0, 'durationMs': 500}}}]}
print(json.dumps(scene))
PYCODE
../run.sh compile $T/ambiguous.excalidraw $T/out.yml
